function handleFabricationInput(el){
  const key=el.name.slice(4),p=state.fabrication;
  if(key==='count'){p.count=Number(el.value);p.preGaps=Array(p.count).fill(null);p.postGaps=Array(p.count).fill(null);p.tackAngles=[];p.edgeCondition='unknown';p.disposition='';renderFitup(true);}
  else if(key.startsWith('pre.')||key.startsWith('post.')){const [phase,index]=key.split('.');p[phase==='pre'?'preGaps':'postGaps'][Number(index)]=el.value===''?null:Number(el.value);p.inspectionKey=geometryRecordKey(state.params);}
  else if(key.startsWith('tack.')){const a=Number(key.slice(5));p.tackAngles=p.tackAngles.filter(v=>v!==a);if(el.checked)p.tackAngles.push(a);}
  else{const value=['stock','markError','cutError','kerf','gapMin','gapMax','bevelAngle','rootFace'].includes(key)?(el.value===''?null:Number(el.value)):el.value;
    if(key==='gapBasis'&&value!==p.gapBasis&&(p.preGaps.some(v=>v!==null)||p.postGaps.some(v=>v!==null))){p.preGaps=Array(p.count).fill(null);p.postGaps=Array(p.count).fill(null);p.edgeCondition='unknown';p.disposition='';renderFitup(true);notify('量測方向或位置改變，請重新量測。');}
    p[key]=value;if(['edgeCondition','disposition'].includes(key))p.inspectionKey=geometryRecordKey(state.params);
  }
  if(key==='stock'&&p.stock!==null&&state.params.hostType==='straight')state.template='branch-rough';pending=true;if(lastValid)$('undo-change').disabled=false;for(const id of ['svg-export','dxf-export','csv-export','report-button','quick-report','print-current-pattern','full-report','step-report'])if($(id))$(id).disabled=true;
  clearTimeout(timer);timer=setTimeout(()=>{if(key==='stock'&&p.stock!==null&&state.params.hostType==='straight')state.template='branch-rough';compute();},120);
}
$('fitup-panel').addEventListener('input',e=>{if(e.target.name?.startsWith('fab.'))handleFabricationInput(e.target);});
